(window.V2_TALK=window.V2_TALK||{})["musee"]={"musee/cantine":[{"id":"V_musee_cantine_01","title":"Le pique-nique du musée","premise":"On a class field trip, Mrs. Petit, Léa and Inès eat lunch in the museum's lunchroom.","cefr":"C2","lines":[{"speaker":"Mme Petit","fr":"Les enfants, on mange vite : à une heure, l'atelier ludique commence.","en":"Kids, let's eat quickly: at one o'clock, the hands-on game workshop starts.","spans":[[52,59,"fr_ludique_adj"]]},{"speaker":"Léa","fr":"Encore des jeux ? Finalement, « musée » n'est pas synonyme d'« ennui » !","en":"More games? So \"museum\" doesn't mean \"boring\" after all!","spans":[[50,58,"fr_synonyme_adj"]]},{"speaker":"Inès","fr":"Madame, l'eau du robinet a un goût bizarre.","en":"Ma'am, the tap water tastes weird.","spans":[]},{"speaker":"Mme Petit","fr":"Elle est très calcaire, ici. Prends plutôt une bouteille.","en":"The water is very hard here. Take a bottle instead.","spans":[[14,22,"fr_calcaire_adj"]]},{"speaker":"Inès","fr":"Léa, pourquoi tu caches ton dessert derrière ton dos ?","en":"Léa, why are you hiding your dessert behind your back?","spans":[]},{"speaker":"Léa","fr":"C'est pour mon frère… Ne le dis à personne !","en":"It's for my brother… Don't tell anyone!","spans":[]},{"speaker":"Mme Petit","fr":"Léa est pudique : elle n'aime pas qu'on voie ses gentillesses.","en":"Léa is shy about it: she doesn't like people to see her kind deeds.","spans":[[8,15,"fr_pudique_adj"]]},{"speaker":"Inès","fr":"Oh ! Une maquette du Capitole de Washington ! Quelle joie indicible !","en":"Oh! A model of the Capitol in Washington! What indescribable joy!","spans":[[58,67,"fr_indicible_adj"]]},{"speaker":"Mme Petit","fr":"Moins fort, Inès ! Avec tout ce bruit, j'ai un mal de tête lancinant.","en":"Not so loud, Inès! With all this noise, I have a throbbing headache.","spans":[[59,68,"fr_lancinant_adj"]]}]}],"musee/emotions":[{"id":"V_musee_emotions_01","title":"Les larmes de joie","premise":"After a little show on the museum stage, the children talk about their feelings.","cefr":"C2","lines":[{"speaker":"Léa","fr":"Maman, Inès pleure !","en":"Mom, Inès is crying!","spans":[]},{"speaker":"Inès","fr":"Mais non, je suis émue ! Le petit spectacle était trop beau.","en":"No, I'm just moved! The little show was so beautiful.","spans":[[18,22,"fr_emu_adj"]]},{"speaker":"Maman","fr":"Inès est très sensible. C'est une qualité.","en":"Inès is very sensitive. That's a good quality.","spans":[[14,22,"fr_sensible_adj"]]},{"speaker":"Léa","fr":"Moi aussi, je suis émotive. J'ai pleuré au film des pingouins.","en":"I'm emotional too. I cried at the penguin movie.","spans":[[19,26,"fr_emotif_adj"]]},{"speaker":"Tom","fr":"Le garçon qui grimpe au mur d'escalade jusqu'en haut est hardi !","en":"The boy climbing all the way to the top of the climbing wall is bold!","spans":[[57,62,"fr_hardi_adj"]]},{"speaker":"Maman","fr":"Et le petit qui crie parce qu'il veut une glace… il est un peu capricieux.","en":"And the little one screaming because he wants ice cream… he's a bit spoiled.","spans":[[63,73,"fr_capricieux_adj"]]},{"speaker":"Léa","fr":"Il est pénible, oui !","en":"He's a pain, yes!","spans":[[7,14,"fr_penible_adj"]]},{"speaker":"Maman","fr":"Ne sois pas hautaine, Léa. Tu faisais pareil à son âge.","en":"Don't be so high and mighty, Léa. You did the same at his age.","spans":[[12,20,"fr_hautain_adj"]]},{"speaker":"Tom","fr":"La comédienne avait un visage très expressif. Elle a un talent enviable.","en":"The actress had a very expressive face. She has an enviable talent.","spans":[[35,44,"fr_expressif_adj"],[63,71,"fr_enviable_adj"]]}]}],"musee/saveurs":[{"id":"V_musee_saveurs_01","title":"L'atelier des saveurs","premise":"Mrs. Roux runs a tasting workshop in the museum kitchen.","cefr":"C1","lines":[{"speaker":"Mme Roux","fr":"Bienvenue à l'atelier des saveurs ! Aujourd'hui, c'est un goûter spécial.","en":"Welcome to the taste workshop! Today it's a special snack.","spans":[[65,72,"fr_special_adj"]]},{"speaker":"Tom","fr":"Je peux goûter le chocolat chaud ?","en":"Can I taste the hot chocolate?","spans":[]},{"speaker":"Mme Roux","fr":"Attention, il est brûlant ! Il est préférable d'attendre une minute.","en":"Careful, it's boiling hot! It's better to wait a minute.","spans":[[18,25,"fr_brulant_adj"],[35,45,"fr_preferable_adj"]]},{"speaker":"Léa","fr":"Moi, je veux la tarte aux fraises. C'est mon dessert favori.","en":"I want the strawberry tart. It's my favorite dessert.","spans":[[53,59,"fr_favori_adj"]]},{"speaker":"Mme Roux","fr":"Tu n'es allergique à rien ?","en":"You're not allergic to anything?","spans":[[8,18,"fr_allergique_adj"]]},{"speaker":"Léa","fr":"Non, juste aux chats !","en":"No, only to cats!","spans":[]},{"speaker":"Mme Roux","fr":"Et pour le bébé, voici une planche avec des boutons et des couleurs : c'est une bonne stimulation pour les sens.","en":"And for the baby, here's a board with buttons and colors: it's good stimulation for the senses.","spans":[[86,97,"fr_stimulation_noun"]]},{"speaker":"Mme Roux","fr":"Bon, qui est désireux d'apprendre la recette du cookie triple chocolat ?","en":"Now, who's eager to learn the recipe for the triple chocolate cookie?","spans":[[13,21,"fr_desireux_adj"],[55,61,"fr_triple_adj"]]},{"speaker":"Tom","fr":"Moi ! C'est vraiment agréable, ici.","en":"Me! It's really nice here.","spans":[[21,29,"fr_agreable_adj"]]}]}],"musee/caracteres":[{"id":"V_musee_caracteres_01","title":"Les portraits sévères","premise":"Mom and Léa stroll through the gallery of character portraits.","cefr":"C1","lines":[{"speaker":"Léa","fr":"Maman, ce directeur sur le tableau a l'air très sévère.","en":"Mom, the principal in that painting looks very strict.","spans":[[48,54,"fr_severe_adj"]]},{"speaker":"Maman","fr":"Oui, il croise les bras. On dirait qu'il va te donner une punition !","en":"Yes, his arms are crossed. He looks like he's about to give you detention!","spans":[]},{"speaker":"Léa","fr":"Et la dame à côté, avec son grand chapeau et ses bijoux ?","en":"And the lady next to him, with her big hat and jewelry?","spans":[]},{"speaker":"Maman","fr":"Elle allait à toutes les soirées mondaines de Paris.","en":"She went to every fancy society party in Paris.","spans":[[33,42,"fr_mondain_adj"]]},{"speaker":"Léa","fr":"Son chapeau est grotesque : il y a un oiseau entier dessus !","en":"Her hat is ridiculous: there's a whole bird on it!","spans":[[16,25,"fr_grotesque_adj"]]},{"speaker":"Maman","fr":"C'était la mode ! Et le guide dit que son mari était très regardant : il comptait chaque centime.","en":"It was the fashion! And the guide says her husband was very tight with money: he counted every penny.","spans":[[58,67,"fr_regardant_adj"]]},{"speaker":"Léa","fr":"Et le vieux capitaine, là ? Il a la peau toute rouge.","en":"And the old captain there? His skin is all red.","spans":[]},{"speaker":"Maman","fr":"En mer, le soleil est implacable. Et le peintre a été impitoyable : il a peint chaque ride.","en":"At sea, the sun is relentless. And the painter was merciless: he painted every wrinkle.","spans":[[22,32,"fr_implacable_adj"],[54,65,"fr_impitoyable_adj"]]},{"speaker":"Léa","fr":"Mais ce portrait de chien, c'est un véritable chef-d'œuvre !","en":"But this portrait of a dog is a real masterpiece!","spans":[[36,45,"fr_veritable_adj"]]}]}],"musee/couleurs":[{"id":"V_musee_couleurs_01","title":"Le caméléon et le faon","premise":"Léa and Dad visit the cabinet of colors, where a painter is at work.","cefr":"C1","lines":[{"speaker":"Léa","fr":"Papa, le peintre utilise un marron très foncé pour le faon.","en":"Dad, the painter is using a very dark brown for the fawn.","spans":[[40,45,"fr_fonce_adj"]]},{"speaker":"Papa","fr":"Et regarde le caméléon : sa couleur est changeante. Il devient vert, puis jaune.","en":"And look at the chameleon: its color keeps changing. It turns green, then yellow.","spans":[[40,50,"fr_changeant_adj"]]},{"speaker":"Léa","fr":"Mme Petit dit que le bleu et l'orange sont des couleurs complémentaires.","en":"Mrs. Petit says blue and orange are complementary colors.","spans":[[56,71,"fr_complementaire_adj"]]},{"speaker":"Papa","fr":"C'est vrai. Ensemble, elles sont éclatantes.","en":"That's right. Together, they're dazzling.","spans":[[33,43,"fr_eclatant_adj"]]},{"speaker":"Léa","fr":"Cette robe sur le tableau est ravissante ! On dirait une fête fastueuse chez un roi.","en":"That dress in the painting is lovely! It looks like a lavish party at a king's palace.","spans":[[30,40,"fr_ravissant_adj"],[62,71,"fr_fastueux_adj"]]},{"speaker":"Papa","fr":"Attention, ne touche pas ! Ces vieilles peintures sont précieuses.","en":"Careful, don't touch! These old paintings are precious.","spans":[[55,65,"fr_precieux_adj"]]},{"speaker":"Léa","fr":"Aïe ! Je me suis griffée sur le cadre… Mais c'est superficiel, c'est rien.","en":"Ouch! I scratched myself on the frame… But it's just a surface scratch, it's nothing.","spans":[[50,61,"fr_superficiel_adj"]]},{"speaker":"Papa","fr":"Ouf, une douleur momentanée. Et après, on fait quoi ?","en":"Phew, it'll only hurt for a moment. So what shall we do next?","spans":[[17,27,"fr_momentane_adj"]]},{"speaker":"Léa","fr":"J'ai une vague idée… une glace ?","en":"I have a vague idea… ice cream?","spans":[[9,14,"fr_vague_adj"]]}]}],"musee/fete":[{"id":"V_musee_fete_01","title":"La fête au musée","premise":"Tom, Léa and Mom enjoy a lively party in the museum's party room.","cefr":"C2","lines":[{"speaker":"Tom","fr":"Cette salle des fêtes est trop cool !","en":"This party room is so cool!","spans":[[31,35,"fr_cool_adj"]]},{"speaker":"Maman","fr":"L'ambiance est très festive, c'est vrai. Mais doucement, Tom !","en":"It's a really festive mood, that's true. But take it easy, Tom!","spans":[[20,27,"fr_festif_adj"]]},{"speaker":"Léa","fr":"Le garçon au skate est turbulent : il a fait tomber les guirlandes.","en":"The boy on the skateboard is rowdy: he knocked down the streamers.","spans":[[23,32,"fr_turbulent_adj"]]},{"speaker":"Maman","fr":"Avec tous ces enfants, c'est un peu chaotique…","en":"With all these kids, it's a little chaotic…","spans":[[36,45,"fr_chaotique_adj"]]},{"speaker":"Tom","fr":"Mais le spectacle de magie était sensationnel !","en":"But the magic show was sensational!","spans":[[33,45,"fr_sensationnel_adj"]]},{"speaker":"Léa","fr":"Regarde, Papi danse aussi ! Il est encore très actif.","en":"Look, Grandpa's dancing too! He's still very active.","spans":[[47,52,"fr_actif_adj"]]},{"speaker":"Maman","fr":"Et très décontracté, avec sa chemise à fleurs.","en":"And very relaxed, in his flowered shirt.","spans":[[8,19,"fr_decontracte_adj"]]},{"speaker":"Tom","fr":"Mon petit discours pour Léa est un peu brouillon. Je l'ai écrit en deux minutes.","en":"My little speech for Léa is a bit messy. I wrote it in two minutes.","spans":[[39,48,"fr_brouillon_adj"]]},{"speaker":"Léa","fr":"Pas grave, je l'aime quand même !","en":"No big deal, I love it anyway!","spans":[]}]}],"musee/voix":[{"id":"V_musee_voix_01","title":"L'enregistrement de la chorale","premise":"Mrs. Petit records the children's choir in the cabinet of voices.","cefr":"C2","lines":[{"speaker":"Mme Petit","fr":"Les enfants, aujourd'hui on enregistre la chorale pour le service audiovisuel du musée.","en":"Kids, today we're recording the choir for the museum's audiovisual department.","spans":[[66,77,"fr_audiovisuel_adj"]]},{"speaker":"Tom","fr":"Madame, la porte est grinçante ! On l'entend sur l'enregistrement.","en":"Ma'am, the door is squeaky! You can hear it on the recording.","spans":[[21,30,"fr_grincant_adj"]]},{"speaker":"Mme Petit","fr":"Je vais la fermer doucement. Léa, ta voix est très aiguë : chante un peu plus bas.","en":"I'll close it gently. Léa, your voice is very high: sing a little lower.","spans":[[51,56,"fr_aigu_adj"]]},{"speaker":"Léa","fr":"D'accord. Mais Inès a la voix tremblante, elle a peur du micro.","en":"OK. But Inès's voice is shaky, she's scared of the mic.","spans":[[30,40,"fr_tremblant_adj"]]},{"speaker":"Inès","fr":"Un peu… Et le pull rose criard de Tom me déconcentre !","en":"A little… And Tom's loud pink sweater is distracting me!","spans":[[24,30,"fr_criard_adj"]]},{"speaker":"Mme Petit","fr":"Bon, on recommence ? Tout le monde lève la main… C'est unanime !","en":"OK, shall we start again? Everyone's raising their hand… It's unanimous!","spans":[[55,62,"fr_unanime_adj"]]},{"speaker":"Tom","fr":"Cette fois, c'était harmonieux, non ?","en":"This time it was harmonious, wasn't it?","spans":[[20,30,"fr_harmonieux_adj"]]},{"speaker":"Mme Petit","fr":"Parfait. Et merci, Tom : tu as été moins volubile entre les chansons !","en":"Perfect. And thank you, Tom: you were less chatty between the songs!","spans":[[41,49,"fr_volubile_adj"]]}]}],"musee/optique":[{"id":"V_musee_optique_01","title":"Le brouillard de la vue","premise":"Mrs. Petit's class explores the cabinet of sight, with its fog, mirrors and a silver moon.","cefr":"C1","lines":[{"speaker":"Mme Petit","fr":"Tom, sois attentif : dans cette salle, on joue avec la perception.","en":"Tom, pay attention: in this room, we play with perception.","spans":[[10,18,"fr_attentif_adj"],[55,65,"fr_perception_noun"]]},{"speaker":"Tom","fr":"Je vois une silhouette derrière la vitre ! C'est un fantôme ?","en":"I can see a silhouette behind the glass! Is it a ghost?","spans":[[12,22,"fr_silhouette_noun"]]},{"speaker":"Mme Petit","fr":"Non, c'est un mannequin. La vitre est floue exprès.","en":"No, it's a mannequin. The glass is blurry on purpose.","spans":[[38,43,"fr_flou_adj"]]},{"speaker":"Léa","fr":"Et avec ce brouillard, la visibilité est nulle !","en":"And with this fog, there's zero visibility!","spans":[[26,36,"fr_visibilite_noun"]]},{"speaker":"Mme Petit","fr":"Regardez la lune argentée au fond. Avec l'éloignement, elle paraît toute petite.","en":"Look at the silver moon at the back. With the distance, it looks tiny.","spans":[[17,25,"fr_argente_adj"],[42,53,"fr_eloignement_noun"]]},{"speaker":"Inès","fr":"Elle a une aura, comme une lumière tout autour.","en":"It has an aura, like a light all around it.","spans":[[11,15,"fr_aura_noun"]]},{"speaker":"Mme Petit","fr":"Bravo, c'est un détail subtil. Les peintres adorent cet effet.","en":"Well done, that's a subtle detail. Painters love that effect.","spans":[[23,29,"fr_subtil_adj"]]},{"speaker":"Tom","fr":"Madame, mes lunettes sont floues aussi !","en":"Ma'am, my glasses are blurry too!","spans":[[26,32,"fr_flou_adj"]]},{"speaker":"Mme Petit","fr":"Ça, Tom, c'est juste de la buée. Essuie-les !","en":"That, Tom, is just fog on your lenses. Wipe them!","spans":[]}]}],"musee/toucher":[{"id":"V_musee_toucher_01","title":"Les boîtes mystère","premise":"With their eyes closed, the children guess what is hidden in the boxes of the cabinet of touch.","cefr":"B2","lines":[{"speaker":"Mme Petit","fr":"Dans le cabinet du toucher, on ferme les yeux et on met la main dans la boîte.","en":"In the cabinet of touch, you close your eyes and put your hand in the box.","spans":[[19,26,"fr_toucher_noun"]]},{"speaker":"Léa","fr":"Brr ! C'est glacé ! Quelle drôle de sensation !","en":"Brr! It's ice-cold! What a strange feeling!","spans":[[12,17,"fr_glace_adj"],[36,45,"fr_sensation_noun"]]},{"speaker":"Mme Petit","fr":"C'est un glaçon. Inès, à toi.","en":"It's an ice cube. Inès, your turn.","spans":[]},{"speaker":"Inès","fr":"C'est mou… et collant ! Beurk, de la pâte à modeler ?","en":"It's soft… and sticky! Yuck, modeling clay?","spans":[[6,9,"fr_mou_adj"],[14,21,"fr_collant_adj"]]},{"speaker":"Tom","fr":"Le mien est pointu ! Un hérisson ?","en":"Mine is pointy! A hedgehog?","spans":[[12,18,"fr_pointu_adj"]]},{"speaker":"Mme Petit","fr":"Non, une pomme de pin. Et l'autre boîte ?","en":"No, a pine cone. And the other box?","spans":[]},{"speaker":"Tom","fr":"Glissant… un savon ! Et celui-ci est rude, comme la barbe de Papi.","en":"Slippery… a bar of soap! And this one is rough, like Grandpa's beard.","spans":[[0,8,"fr_glissant_adj"],[37,41,"fr_rude_adj"]]},{"speaker":"Mme Petit","fr":"Le toucher demande de la sensibilité. Que dit votre instinct pour la dernière boîte ?","en":"Touch takes sensitivity. What does your instinct say about the last box?","spans":[[3,10,"fr_toucher_noun"],[25,36,"fr_sensibilite_noun"],[52,60,"fr_instinct_noun"]]},{"speaker":"Léa","fr":"Rien… ça ne pèse rien du tout ! Une plume ?","en":"Nothing… it weighs nothing at all! A feather?","spans":[]},{"speaker":"Mme Petit","fr":"Oui ! Quelle légèreté !","en":"Yes! How light it is!","spans":[[13,21,"fr_legerete_noun"]]}]}],"musee/parfums":[{"id":"V_musee_parfums_01","title":"Le nez de Papi","premise":"Grandpa Henri tests the children's sense of smell in the cabinet of scents.","cefr":"C1","lines":[{"speaker":"Papi Henri","fr":"Ici, c'est le cabinet des parfums. Il faut un bon odorat !","en":"This is the cabinet of scents. You need a good sense of smell!","spans":[[50,56,"fr_odorat_noun"]]},{"speaker":"Léa","fr":"Ce flacon sent la vanille. Quelle fragrance !","en":"This bottle smells of vanilla. What a fragrance!","spans":[[34,43,"fr_fragrance_noun"]]},{"speaker":"Papi Henri","fr":"Et celui-ci ? De la mangue et de la noix de coco… très exotique.","en":"And this one? Mango and coconut… very exotic.","spans":[[55,63,"fr_exotique_adj"]]},{"speaker":"Tom","fr":"Beurk ! Celui-là sent le vieux fromage. C'est désagréable !","en":"Yuck! That one smells like old cheese. It's unpleasant!","spans":[[46,57,"fr_desagreable_adj"]]},{"speaker":"Léa","fr":"Regarde Tom : il fait une grimace de dégoût !","en":"Look at Tom: he's making a face of disgust!","spans":[[37,43,"fr_degout_noun"]]},{"speaker":"Papi Henri","fr":"Ha ha ! Celui-ci est amer, comme le café noir. Et celui-là est suave, comme une rose.","en":"Ha ha! This one is bitter, like black coffee. And that one is smooth and sweet, like a rose.","spans":[[21,25,"fr_amer_adj"],[63,68,"fr_suave_adj"]]},{"speaker":"Tom","fr":"Le café, c'est amer, mais les croissants sont savoureux !","en":"Coffee is bitter, but croissants are delicious!","spans":[[15,19,"fr_amer_adj"],[46,55,"fr_savoureux_adj"]]},{"speaker":"Papi Henri","fr":"Toujours gourmand ! Sens plutôt l'effluve qui vient de la fenêtre…","en":"Always hungry! Smell the waft coming through the window instead…","spans":[[34,41,"fr_effluve_noun"]]},{"speaker":"Léa","fr":"La boulangerie ! Voilà une subtilité que Tom comprend !","en":"The bakery! Now that's a subtlety Tom understands!","spans":[[27,36,"fr_subtilite_noun"]]}]}],"musee/chateau":[{"id":"V_musee_chateau_01","title":"Le trésor du château","premise":"Dad shows Tom and Léa the castle model and its ramparts, keep and dungeon.","cefr":"C2","lines":[{"speaker":"Tom","fr":"Regarde la maquette du château ! Une vraie forteresse !","en":"Look at the castle model! A real fortress!","spans":[[23,30,"fr_chateau_noun"],[43,53,"fr_forteresse_noun"]]},{"speaker":"Papa","fr":"Ce grand rempart, c'était sa défense. Personne ne pouvait entrer sans permission.","en":"This big rampart was its defense. Nobody could get in without permission.","spans":[[9,16,"fr_rempart_noun"],[29,36,"fr_defense_noun"]]},{"speaker":"Léa","fr":"Et la petite figurine en haut de la tour ?","en":"And the little figure at the top of the tower?","spans":[]},{"speaker":"Papa","fr":"C'est une sentinelle. Elle surveillait la route depuis le donjon.","en":"That's a sentry. She watched the road from the keep.","spans":[[10,20,"fr_sentinelle_noun"],[58,64,"fr_donjon_noun"]]},{"speaker":"Tom","fr":"Et cette tour carrée, au bout du mur ?","en":"And that square tower at the end of the wall?","spans":[]},{"speaker":"Papa","fr":"C'est un bastion. Chaque bloc de pierre pesait une tonne !","en":"That's a bastion. Every block of stone weighed a ton!","spans":[[9,16,"fr_bastion_noun"],[25,29,"fr_bloc_noun"]]},{"speaker":"Léa","fr":"Il y a un carrosse doré dans la cour ! Et le trésor, il est où ?","en":"There's a golden carriage in the courtyard! And where's the treasure?","spans":[[10,18,"fr_carrosse_noun"],[45,51,"fr_tresor_noun"]]},{"speaker":"Papa","fr":"Peut-être au fond de l'oubliette, sous le château !","en":"Maybe at the bottom of the dungeon pit, under the castle!","spans":[[23,32,"fr_oubliette_noun"],[42,49,"fr_chateau_noun"]]},{"speaker":"Tom","fr":"Je veux voir ! Oh non, la petite porte est fermée.","en":"I want to see! Oh no, the little door is shut.","spans":[]},{"speaker":"Papa","fr":"C'est un blocage de sécurité. Ton trésor va tomber aux oubliettes !","en":"It's a safety lock. Your treasure is going to be forgotten!","spans":[[9,16,"fr_blocage_noun"],[34,40,"fr_tresor_noun"],[55,65,"fr_oubliette_noun"]]}]}],"musee/peinture":[{"id":"V_musee_peinture_01","title":"Le portrait de Léa","premise":"In the painting gallery, Léa finds a portrait that looks like her, and Grandpa Henri explains frescoes and frames.","cefr":"C1","lines":[{"speaker":"Léa","fr":"Papi, regarde ce portrait de petite fille. Elle me ressemble !","en":"Grandpa, look at this portrait of a little girl. She looks like me!","spans":[[17,25,"fr_portrait_noun"]]},{"speaker":"Papi Henri","fr":"C'est vrai ! Le peintre a pris sa propre fille comme modèle.","en":"That's true! The painter used his own daughter as a model.","spans":[[16,23,"fr_peintre_noun"],[53,59,"fr_modele_noun"]]},{"speaker":"Tom","fr":"Et ce grand dessin sur le mur ?","en":"And this big drawing on the wall?","spans":[]},{"speaker":"Papi Henri","fr":"C'est une fresque : une peinture murale faite directement sur le plâtre frais.","en":"That's a fresco: a mural painting done straight onto fresh plaster.","spans":[[10,17,"fr_fresque_noun"],[24,32,"fr_peinture_noun"],[33,39,"fr_mural_adj"]]},{"speaker":"Léa","fr":"Et à côté, la tapisserie avec des licornes ! J'adore le motif.","en":"And next to it, the tapestry with unicorns! I love the pattern.","spans":[[14,24,"fr_tapisserie_noun"],[56,61,"fr_motif_noun"]]},{"speaker":"Tom","fr":"Ce tableau-là a un cadre doré énorme.","en":"That painting has a huge golden frame.","spans":[[19,24,"fr_cadre_noun"]]},{"speaker":"Papi Henri","fr":"Parfois, l'encadrement coûte plus cher que la toile !","en":"Sometimes the framing costs more than the canvas!","spans":[[11,22,"fr_encadrement_noun"],[46,51,"fr_toile_noun"]]},{"speaker":"Léa","fr":"Pourquoi le ciel est plus clair à cet endroit ?","en":"Why is the sky lighter in this spot?","spans":[]},{"speaker":"Papi Henri","fr":"C'est une retouche : le restaurateur a réparé un petit trou.","en":"That's a touch-up: the restorer repaired a small hole.","spans":[[10,18,"fr_retouche_noun"]]}]}],"musee/medecine":[{"id":"V_musee_medecine_01","title":"Les maladies d'autrefois","premise":"Tom asks Grandpa Henri about the jars and old posters in the history-of-medicine gallery.","cefr":"C2","lines":[{"speaker":"Tom","fr":"Papi, pourquoi il y a des bocaux partout dans cette galerie ?","en":"Grandpa, why are there jars everywhere in this gallery?","spans":[]},{"speaker":"Papi Henri","fr":"C'est l'histoire de la médecine. Chaque vitrine présente une pathologie, une maladie.","en":"It's the history of medicine. Each case shows a pathology, a disease.","spans":[[61,71,"fr_pathologie_noun"]]},{"speaker":"Tom","fr":"Le choléra, c'est quoi ?","en":"What's cholera?","spans":[[3,10,"fr_cholera_noun"]]},{"speaker":"Papi Henri","fr":"Une maladie qui venait de l'eau sale. Autrefois, la contagion allait très vite.","en":"A disease that came from dirty water. In the old days, it spread very fast.","spans":[[52,61,"fr_contagion_noun"]]},{"speaker":"Tom","fr":"Et la tuberculose ?","en":"And tuberculosis?","spans":[[6,17,"fr_tuberculose_noun"]]},{"speaker":"Papi Henri","fr":"Une infection des poumons. Avec les vaccins et l'eau propre, la mortalité a beaucoup baissé.","en":"A lung infection. With vaccines and clean water, the death rate has dropped a lot.","spans":[[4,13,"fr_infection_noun"],[64,73,"fr_mortalite_noun"]]},{"speaker":"Tom","fr":"Et cette affiche sur la famine ?","en":"And this poster about famine?","spans":[[24,30,"fr_famine_noun"]]},{"speaker":"Papi Henri","fr":"Quand on manquait de nourriture, les gens tombaient malades plus facilement.","en":"When people didn't have enough food, they got sick more easily.","spans":[]},{"speaker":"Tom","fr":"Ici, on mesure le sucre dans le sang. C'est pour le diabète ?","en":"Here they measure the sugar in your blood. Is that for diabetes?","spans":[[32,36,"fr_sang_noun"],[52,59,"fr_diabete_noun"]]},{"speaker":"Papi Henri","fr":"Exactement. Et rassure-toi : ta peur des piqûres n'est pas pathologique !","en":"Exactly. And don't worry: your fear of shots isn't pathological!","spans":[[59,71,"fr_pathologique_adj"]]}]}],"musee/atelier":[{"id":"V_musee_atelier_01","title":"L'oiseau qui s'envole","premise":"In the children's workshop, the class illustrates a picture book and turns it into a little animation.","cefr":"B2","lines":[{"speaker":"Mme Petit","fr":"Bienvenue à l'atelier des enfants ! Aujourd'hui, chacun fait une illustration pour notre livre.","en":"Welcome to the children's workshop! Today everyone makes an illustration for our book.","spans":[[65,77,"fr_illustration_noun"]]},{"speaker":"Léa","fr":"Moi, je fais un dessin de Papi dans son jardin.","en":"I'm doing a drawing of Grandpa in his garden.","spans":[[16,22,"fr_dessin_noun"]]},{"speaker":"Inès","fr":"Moi, un petit oiseau avec une blessure à l'aile. La vétérinaire le soigne.","en":"I'm doing a little bird with a hurt wing. The vet is taking care of it.","spans":[[30,38,"fr_blessure_noun"]]},{"speaker":"Mme Petit","fr":"Très joli ! Prends un pinceau fin pour les plumes.","en":"Very pretty! Use a thin brush for the feathers.","spans":[[22,29,"fr_pinceau_noun"]]},{"speaker":"Tom","fr":"Madame, on peut faire bouger les dessins ?","en":"Ma'am, can we make the drawings move?","spans":[[33,40,"fr_dessin_noun"]]},{"speaker":"Mme Petit","fr":"Oui, c'est le principe de l'animation : beaucoup d'images, l'une après l'autre.","en":"Yes, that's how animation works: lots of pictures, one after another.","spans":[[28,37,"fr_animation_noun"]]},{"speaker":"Tom","fr":"Alors, dans la dernière image, l'oiseau d'Inès est guéri et il s'envole !","en":"So in the last picture, Inès's bird is all better and flies away!","spans":[]},{"speaker":"Inès","fr":"Super idée !","en":"Great idea!","spans":[]}]}],"musee/classe":[{"id":"V_musee_classe_01","title":"Le jeu des sons","premise":"Mrs. Petit runs a learning game in the museum classroom.","cefr":"C2","lines":[{"speaker":"Mme Petit","fr":"Tout le monde est assis ? Bien. Cet atelier est didactique : on apprend en jouant.","en":"Is everyone seated? Good. This workshop is educational: we learn by playing.","spans":[[18,23,"fr_assis_adj"],[48,58,"fr_didactique_adj"]]},{"speaker":"Tom","fr":"Madame, le jeu de l'alphabet phonétique est ardu !","en":"Ma'am, the phonetic alphabet game is hard!","spans":[[29,39,"fr_phonetique_adj"],[44,48,"fr_ardu_adj"]]},{"speaker":"Mme Petit","fr":"Un peu, mais tu progresses. Léa, ton histoire est cohérente ?","en":"A little, but you're getting better. Léa, does your story hang together?","spans":[[50,59,"fr_coherent_adj"]]},{"speaker":"Léa","fr":"Oui : le début, le milieu et la fin vont ensemble !","en":"Yes: the beginning, the middle and the end all fit!","spans":[]},{"speaker":"Inès","fr":"Et moi, j'ai gagné la partie. C'est incontestable !","en":"And I won the game. No one can argue with that!","spans":[[36,49,"fr_incontestable_adj"]]},{"speaker":"Mme Petit","fr":"Bravo, Inès. Tom, tu es conscient de l'heure ? Il reste cinq minutes.","en":"Well done, Inès. Tom, are you aware of the time? There are five minutes left.","spans":[[24,33,"fr_conscient_adj"]]},{"speaker":"Tom","fr":"Déjà ? On arrive à l'étape terminale du jeu !","en":"Already? We're getting to the final stage of the game!","spans":[[27,36,"fr_terminal_adj"]]},{"speaker":"Mme Petit","fr":"Alors on range. Et sois civil : laisse passer les filles devant le placard.","en":"Then let's tidy up. And be polite: let the girls go first at the cupboard.","spans":[[24,29,"fr_civil_adj"]]}]}],"musee/musee":[{"id":"C_R_art_01","title":"Au musée d'Orsay","premise":"Two friends visit the Musée d'Orsay and discuss the paintings.","cefr":"A2","lines":[{"speaker":"Laure","fr":"Regarde ce tableau de Monet ! Les couleurs sont incroyables.","en":"Look at this Monet painting! The colors are incredible.","spans":[]},{"speaker":"Mehdi","fr":"Oui. Il peignait toujours dehors, sur sa toile, devant le paysage.","en":"Yes. He always painted outdoors, on his canvas, in front of the landscape.","spans":[]},{"speaker":"Laure","fr":"J'adore la peinture impressionniste.","en":"I love Impressionist painting.","spans":[]},{"speaker":"Mehdi","fr":"Moi, je préfère les dessins de Degas. Les danseuses !","en":"I prefer Degas's drawings. The dancers!","spans":[]},{"speaker":"Laure","fr":"Ce musée a des œuvres magnifiques.","en":"This museum has magnificent works.","spans":[[3,8,"fr_musee_noun"],[15,21,"fr_oeuvre_noun_f"]]},{"speaker":"Mehdi","fr":"C'est une ancienne gare, tu savais ?","en":"It's a former train station, did you know?","spans":[]},{"speaker":"Laure","fr":"Non ! C'est génial, l'art dans une gare.","en":"No! That's brilliant, art in a station.","spans":[[22,25,"fr_art_noun"]]},{"speaker":"Mehdi","fr":"La culture, ça devrait être gratuit pour tout le monde.","en":"Culture should be free for everyone.","spans":[[3,10,"fr_culture_noun"]]},{"speaker":"Laure","fr":"C'est gratuit pour les moins de vingt-six ans !","en":"It's free for under twenty-sixes!","spans":[]},{"speaker":"Mehdi","fr":"Encore deux ans pour moi, alors !","en":"Two more years for me, then!","spans":[]}]}],"musee/sculpture":[{"id":"C_R_art_02","title":"L'atelier du sculpteur","premise":"A young woman visits a sculptor's workshop to commission a portrait.","cefr":"B1","lines":[{"speaker":"Hélène","fr":"Bonjour. Je voudrais un portrait de mon père pour ses quatre-vingts ans.","en":"Hello. I'd like a portrait of my father for his eightieth birthday.","spans":[]},{"speaker":"le sculpteur","fr":"En peinture ou en sculpture ?","en":"A painting or a sculpture?","spans":[[18,27,"fr_sculpture_noun"]]},{"speaker":"Hélène","fr":"Une sculpture, un petit buste.","en":"A sculpture, a small bust.","spans":[[4,13,"fr_sculpture_noun"]]},{"speaker":"le sculpteur","fr":"Très bien. J'ai besoin de photos. Je travaille d'abord avec un pinceau, pour le dessin, puis avec l'argile.","en":"Very good. I need photos. First I work with a brush for the sketch, then with clay.","spans":[]},{"speaker":"Hélène","fr":"Votre atelier est magnifique. Et cette tapisserie au mur ?","en":"Your studio is magnificent. And that tapestry on the wall?","spans":[]},{"speaker":"le sculpteur","fr":"C'est le travail de ma femme. Elle fait aussi des films d'animation.","en":"That's my wife's work. She also makes animated movies.","spans":[]},{"speaker":"Hélène","fr":"Une famille très artistique !","en":"A very artistic family!","spans":[[17,27,"fr_artistique_adj"]]},{"speaker":"le sculpteur","fr":"Ha ha ! Pour votre buste, je ne veux pas d'artifice : il faut voir son vrai visage.","en":"Ha ha! For your bust, I don't want any tricks: you need to see his real face.","spans":[[43,51,"fr_artifice_noun"]]},{"speaker":"Hélène","fr":"Parfait. Et le prix, à l'unité ?","en":"Perfect. And the price per piece?","spans":[[25,30,"fr_unite_noun"]]},{"speaker":"le sculpteur","fr":"Huit cents euros. Il sera prêt dans un mois.","en":"Eight hundred euros. It'll be ready in a month.","spans":[]}]}],"musee/vernissage":[{"id":"C_R_art_03","title":"L'exposition de fin d'année","premise":"Two art students prepare their end-of-year exhibition.","cefr":"C1","lines":[{"speaker":"Inès","fr":"Le catalogue de l'exposition est prêt ?","en":"Is the exhibition catalog ready?","spans":[[3,12,"fr_catalogue_noun"]]},{"speaker":"Romain","fr":"Presque. J'attends les photos de ta fresque.","en":"Almost. I'm waiting for the photos of your mural.","spans":[]},{"speaker":"Inès","fr":"Elle est enfin finie ! Trois mois d'élaboration.","en":"It's finally finished! Three months of work.","spans":[[36,47,"fr_elaboration_noun"]]},{"speaker":"Romain","fr":"Elle est magnifique. Le jury va adorer ta créativité.","en":"It's magnificent. The jury will love your creativity.","spans":[[42,52,"fr_creativite_noun"]]},{"speaker":"Inès","fr":"Merci. Et tes affiches ? Tu as choisi un design ?","en":"Thanks. And your posters? Have you chosen a design?","spans":[[41,47,"fr_design_noun"]]},{"speaker":"Romain","fr":"Oui, très simple, noir et blanc. Il me reste l'encadrement des dessins.","en":"Yes, very simple, black and white. I've still got to frame the drawings.","spans":[]},{"speaker":"Inès","fr":"Il y a aussi un concert, le soir du vernissage ?","en":"Is there a concert too, on the opening night?","spans":[]},{"speaker":"Romain","fr":"Oui, des élèves du conservatoire viennent jouer du violon.","en":"Yes, students from the music academy are coming to play the violin.","spans":[[19,32,"fr_conservatoire_noun"]]},{"speaker":"Inès","fr":"Super. Et ta sculpture en carton, c'est un simulacre de statue antique ?","en":"Great. And your cardboard sculpture, is it a mock antique statue?","spans":[[43,52,"fr_simulacre_noun"]]},{"speaker":"Romain","fr":"Exactement ! Une fausse statue grecque, pour faire rire.","en":"Exactly! A fake Greek statue, to make people laugh.","spans":[]}]}],"musee/noblesse":[{"id":"C_R_heraldry_01","title":"La visite du château fort","premise":"A boy visits a medieval castle with his mother.","cefr":"B1","lines":[{"speaker":"Théo","fr":"Maman, regarde ce château ! Il est énorme.","en":"Mom, look at this castle! It's huge.","spans":[]},{"speaker":"Maman","fr":"C'était le château du baron de Montfort, au douzième siècle.","en":"It was the castle of the Baron of Montfort, in the twelfth century.","spans":[[22,27,"fr_baron_noun"]]},{"speaker":"Théo","fr":"Il y avait des chevaliers ?","en":"Were there knights?","spans":[]},{"speaker":"Maman","fr":"Oui. Regarde, dans cette salle, l'épée d'un chevalier.","en":"Yes. Look, in this room, a knight's sword.","spans":[]},{"speaker":"Théo","fr":"Elle est lourde ! Et ces murs, ils sont très épais.","en":"It's heavy! And these walls are really thick.","spans":[]},{"speaker":"Maman","fr":"Pour la défense. Chaque bloc de pierre pèse une tonne.","en":"For defense. Each block of stone weighs a ton.","spans":[]},{"speaker":"Théo","fr":"Le baron, il était roi ?","en":"Was the baron a king?","spans":[[3,8,"fr_baron_noun"]]},{"speaker":"Maman","fr":"Non, il n'avait pas de couronne. Mais il vivait avec tout son entourage : soldats, serviteurs, famille.","en":"No, he didn't have a crown. But he lived with his whole entourage: soldiers, servants, family.","spans":[[23,31,"fr_couronne_noun"],[62,71,"fr_entourage_noun"]]},{"speaker":"Théo","fr":"Je peux acheter une épée en bois à la boutique ?","en":"Can I buy a wooden sword at the shop?","spans":[]},{"speaker":"Maman","fr":"D'accord, mais pas de combat avec ta sœur !","en":"OK, but no fighting with your sister!","spans":[]}]}],"musee/chevaliers":[{"id":"C_R_heraldry_02","title":"Le spectacle médiéval","premise":"Two friends watch a medieval show at a castle.","cefr":"C1","lines":[{"speaker":"Lola","fr":"Regarde, le spectacle commence au pied du donjon !","en":"Look, the show's starting at the foot of the keep!","spans":[]},{"speaker":"Quentin","fr":"C'est un duel entre deux chevaliers.","en":"It's a duel between two knights.","spans":[[9,13,"fr_duel_noun"]]},{"speaker":"Lola","fr":"Celui de droite a un sabre ! Ce n'est pas un peu bizarre pour un chevalier ?","en":"The one on the right has a curved sword! Isn't that a bit strange for a knight?","spans":[[21,26,"fr_sabre_noun"]]},{"speaker":"Quentin","fr":"Il revient de croisade, il l'a ramené d'Orient.","en":"He's back from a crusade, he brought it back from the East.","spans":[[14,22,"fr_croisade_noun"]]},{"speaker":"Lola","fr":"Et le jeune homme derrière ?","en":"And the young man behind?","spans":[]},{"speaker":"Quentin","fr":"C'est son écuyer. Il porte son bouclier.","en":"That's his squire. He carries his shield.","spans":[[10,16,"fr_ecuyer_noun"]]},{"speaker":"Lola","fr":"Et la dame en bleu ?","en":"And the lady in blue?","spans":[]},{"speaker":"Quentin","fr":"La dame de la seigneurie. Le chevalier est son protecteur.","en":"The lady of the manor. The knight is her protector.","spans":[[47,57,"fr_protecteur_noun"]]},{"speaker":"Lola","fr":"Quel enchantement, ces costumes !","en":"These costumes are enchanting!","spans":[[5,17,"fr_enchantement_noun"]]},{"speaker":"Quentin","fr":"Oui, et regarde, il gagne !","en":"Yes, and look, he's winning!","spans":[]}]}],"musee/armes":[{"id":"C_R_text_crime_01","title":"Le roman policier","premise":"Two friends discuss the crime novel they're both reading for their book club.","cefr":"B1","lines":[{"speaker":"Pauline","fr":"Tu en es où dans le roman ?","en":"How far have you got in the novel?","spans":[]},{"speaker":"Arthur","fr":"Au chapitre dix, quand l'inspecteur trouve la cabane dans la forêt.","en":"Chapter ten, when the inspector finds the hut in the forest.","spans":[]},{"speaker":"Pauline","fr":"Ah ! Avec la hache et le vieux fusil ?","en":"Ah! With the axe and the old rifle?","spans":[[13,18,"fr_hache_noun"],[31,36,"fr_fusil_noun"]]},{"speaker":"Arthur","fr":"Oui. Mais ce n'est pas l'arme du crime, je pense.","en":"Yes. But I don't think it's the murder weapon.","spans":[[25,29,"fr_arme_noun"]]},{"speaker":"Pauline","fr":"Je ne dis rien ! Mais la bagarre au bar, au début, c'est important.","en":"I'm not saying anything! But the fight in the bar at the beginning is important.","spans":[]},{"speaker":"Arthur","fr":"Le pistolet de l'inspecteur a disparu à ce moment-là...","en":"The inspector's gun disappeared at that moment...","spans":[[3,11,"fr_pistolet_noun"]]},{"speaker":"Pauline","fr":"Exactement. Et la lance africaine sur le mur du salon, tu l'as remarquée ?","en":"Exactly. And the African spear on the living-room wall, did you notice it?","spans":[[18,23,"fr_lance_noun"]]},{"speaker":"Arthur","fr":"Oui ! Et la bombe de peinture dans le garage. Tant d'indices !","en":"Yes! And the spray paint can in the garage. So many clues!","spans":[[12,17,"fr_bombe_noun"]]},{"speaker":"Pauline","fr":"Finis vite, on en parle jeudi au club !","en":"Finish it quickly, we'll talk about it on Thursday at the club!","spans":[]},{"speaker":"Arthur","fr":"Promis !","en":"Promise!","spans":[]}]}],"musee/enquete":[{"id":"C_R_text_crime_02","title":"La série policière","premise":"A couple watch a detective series on TV.","cefr":"B1","lines":[{"speaker":"Nadia","fr":"Alors, qui est le meurtrier, à ton avis ?","en":"So who's the murderer, in your opinion?","spans":[]},{"speaker":"Franck","fr":"Le jardinier ! Il a un revolver dans sa voiture.","en":"The gardener! He's got a revolver in his car.","spans":[]},{"speaker":"Nadia","fr":"Trop évident. Moi, je pense que c'est la sœur.","en":"Too obvious. I think it's the sister.","spans":[]},{"speaker":"Franck","fr":"La sœur ? Mais elle était en prison au moment du crime !","en":"The sister? But she was in prison at the time of the crime!","spans":[[29,35,"fr_prison_noun"],[49,54,"fr_crime_noun"]]},{"speaker":"Nadia","fr":"Justement, c'est un alibi parfait.","en":"Exactly, it's the perfect alibi.","spans":[]},{"speaker":"Franck","fr":"Et le voleur de bijoux de l'épisode deux ?","en":"And the jewel thief from episode two?","spans":[[6,12,"fr_voleur_noun"]]},{"speaker":"Nadia","fr":"Il n'est pas un tueur, c'est un petit voleur.","en":"He's not a killer, he's just a petty thief.","spans":[[38,44,"fr_voleur_noun"]]},{"speaker":"Franck","fr":"Attends, la police donne l'assaut à la maison !","en":"Wait, the police are storming the house!","spans":[[27,33,"fr_assaut_noun"]]},{"speaker":"Nadia","fr":"Chut ! On va savoir qui est l'assassin.","en":"Shh! We're about to find out who the murderer is.","spans":[[30,38,"fr_assassin_noun"]]},{"speaker":"Franck","fr":"Je le savais ! C'est le meurtre parfait... de la sœur !","en":"I knew it! The perfect murder... by the sister!","spans":[]},{"speaker":"Nadia","fr":"Ha ha ! Tu disais le jardinier !","en":"Ha ha! You said the gardener!","spans":[]}]}],"musee/mots_deuil":[{"id":"C_R_text_death","title":"Le deuil","premise":"Two cousins talk after the funeral of their grandfather.","cefr":"B2","lines":[{"speaker":"Camille","fr":"C'était une belle cérémonie. Papi aurait aimé.","en":"It was a beautiful ceremony. Grandpa would have liked it.","spans":[]},{"speaker":"Benjamin","fr":"Oui. Sa mort a été un choc pour tout le monde.","en":"Yes. His death was a shock for everyone.","spans":[[8,12,"fr_mort_noun_m"]]},{"speaker":"Camille","fr":"Mamie est en deuil, mais elle tient le coup.","en":"Grandma is in mourning, but she's holding up.","spans":[[13,18,"fr_deuil_noun"]]},{"speaker":"Benjamin","fr":"Tu te souviens quand il jouait aux dés avec nous ? Il trichait toujours !","en":"Do you remember when he played dice with us? He always cheated!","spans":[]},{"speaker":"Camille","fr":"Ha ha ! Oui. Et il racontait des histoires de château, avec le bourreau et la salle de torture.","en":"Ha ha! Yes. And he told castle stories, with the executioner and the torture chamber.","spans":[[63,71,"fr_bourreau_noun"]]},{"speaker":"Benjamin","fr":"On avait si peur !","en":"We were so scared!","spans":[]},{"speaker":"Camille","fr":"Il disait que les embouteillages de Paris, c'était l'enfer sur terre.","en":"He used to say Paris traffic jams were hell on earth.","spans":[]},{"speaker":"Benjamin","fr":"C'est vrai !","en":"That's true!","spans":[]},{"speaker":"Camille","fr":"Et quand il trouvait une bouteille vide, il disait : « Encore un cadavre ! »","en":"And when he found an empty bottle, he'd say: \"Another dead soldier!\"","spans":[[65,72,"fr_cadavre_noun"]]},{"speaker":"Benjamin","fr":"Ha ha ! Il nous manque déjà.","en":"Ha ha! We miss him already.","spans":[]},{"speaker":"Camille","fr":"Oui. Mamie dit qu'un mort n'est jamais vraiment parti tant qu'on parle de lui.","en":"Yes. Grandma says the dead are never really gone as long as we talk about them.","spans":[[21,25,"fr_mort_noun_m"]]},{"speaker":"Benjamin","fr":"On va passer plus de temps avec elle.","en":"We'll spend more time with her.","spans":[]}]}],"musee/jardin":[{"id":"C_R_adj_senses_02","title":"Le week-end à la campagne","premise":"Two friends describe their weekend at a guest house in the countryside.","cefr":"A2","lines":[{"speaker":"Margot","fr":"Alors, ce week-end à la campagne ?","en":"So, how was the weekend in the country?","spans":[]},{"speaker":"Lucas","fr":"Très agréable ! La maison d'hôtes est dans un endroit tranquille, au milieu des vignes.","en":"Very nice! The guest house is in a quiet spot, in the middle of the vineyards.","spans":[[54,64,"fr_tranquille_adj"]]},{"speaker":"Margot","fr":"Et la cuisine ?","en":"And the food?","spans":[]},{"speaker":"Lucas","fr":"Un véritable bonheur. Tout est naturel, les légumes viennent du jardin.","en":"A real delight. Everything's natural, the vegetables come from the garden.","spans":[[31,38,"fr_naturel_adj"]]},{"speaker":"Margot","fr":"Tu as fait quoi ?","en":"What did you do?","spans":[]},{"speaker":"Lucas","fr":"Une randonnée. Je suis quelqu'un d'actif, je ne reste pas assis !","en":"A hike. I'm an active person, I don't sit still!","spans":[]},{"speaker":"Margot","fr":"Et ta copine ?","en":"And your girlfriend?","spans":[]},{"speaker":"Lucas","fr":"Elle a la peau sensible, elle est restée à l'ombre pour lire.","en":"She has sensitive skin, she stayed in the shade to read.","spans":[]},{"speaker":"Margot","fr":"Ce genre de moment, c'est précieux.","en":"Moments like that are precious.","spans":[]},{"speaker":"Lucas","fr":"Oui, c'était un week-end spécial. On a fêté nos deux ans !","en":"Yes, it was a special weekend. We celebrated two years together!","spans":[]}]}],"musee/matieres":[{"id":"C_R_adj_senses_03","title":"Le nouveau prof de maths","premise":"Two high-school students talk about their strict new math teacher.","cefr":"B2","lines":[{"speaker":"Noé","fr":"Le nouveau prof de maths est vraiment sévère !","en":"The new math teacher is really strict!","spans":[]},{"speaker":"Jade","fr":"Oui, il a une voix aiguë et un regard rude.","en":"Yes, he's got a high-pitched voice and a harsh look.","spans":[]},{"speaker":"Noé","fr":"Et il se tient toujours très raide, comme un soldat.","en":"And he always stands really stiffly, like a soldier.","spans":[[29,34,"fr_raide_adj"]]},{"speaker":"Jade","fr":"Ses cours sont pénibles. Trois heures de géométrie !","en":"His lessons are tiresome. Three hours of geometry!","spans":[]},{"speaker":"Noé","fr":"Mais il est civil, il ne crie jamais.","en":"But he's polite, he never shouts.","spans":[]},{"speaker":"Jade","fr":"C'est vrai. Il a dit qu'il était militaire avant ? J'ai un vague souvenir.","en":"That's true. Did he say he was in the army before? I vaguely remember something.","spans":[]},{"speaker":"Noé","fr":"Non, il était ingénieur. Il vient de la vie civile.","en":"No, he was an engineer. He comes from civilian life.","spans":[]},{"speaker":"Jade","fr":"Et tu as vu son crâne ? Lisse comme un œuf !","en":"And have you seen his head? Smooth as an egg!","spans":[[24,29,"fr_lisse_adj"]]},{"speaker":"Noé","fr":"Chut, il arrive !","en":"Shh, he's coming!","spans":[]}]}],"musee/sons":[{"id":"C_R_adj_senses_05","title":"Le téléphone de Papi","premise":"A woman calls her hard-of-hearing grandfather on the phone.","cefr":"B2","lines":[{"speaker":"Léa","fr":"Allô, Papi ? C'est Léa !","en":"Hello, Grandpa? It's Léa!","spans":[]},{"speaker":"Papi","fr":"Quoi ? Parle plus fort, je suis un peu sourd !","en":"What? Speak up, I'm a bit deaf!","spans":[[39,44,"fr_sourd_adj"]]},{"speaker":"Léa","fr":"C'est Léa ! Tu es assis ? J'ai une grande nouvelle.","en":"It's Léa! Are you sitting down? I've got big news.","spans":[]},{"speaker":"Papi","fr":"Oui, je suis dans mon fauteuil. Qu'est-ce qui se passe ?","en":"Yes, I'm in my armchair. What's going on?","spans":[]},{"speaker":"Léa","fr":"Je suis enceinte !","en":"I'm pregnant!","spans":[]},{"speaker":"Papi","fr":"Oh ! Ma voix est toute tremblante, ma chérie... C'est merveilleux !","en":"Oh! My voice is all shaky, darling... That's wonderful!","spans":[]},{"speaker":"Léa","fr":"Je sais que la ligne téléphonique est mauvaise, mais je voulais te le dire directement.","en":"I know the phone line is bad, but I wanted to tell you myself.","spans":[]},{"speaker":"Papi","fr":"Tu es consciente du bonheur que tu me donnes ?","en":"Do you realize how happy you've made me?","spans":[]},{"speaker":"Léa","fr":"Oui, Papi ! Et j'ai les mains glacées, tellement je suis émue.","en":"Yes, Grandpa! And my hands are icy, I'm so emotional.","spans":[]},{"speaker":"Papi","fr":"C'est cool, comme disent les jeunes !","en":"It's cool, as the young people say!","spans":[]},{"speaker":"Léa","fr":"Ha ha ! Ton rire est toujours aussi sonore !","en":"Ha ha! Your laugh is as loud as ever!","spans":[[36,42,"fr_sonore_adj"]]}]},{"id":"C_R_abs_senses_03","title":"Le voisin bruyant","premise":"A tenant complains to the building manager about noise from upstairs.","cefr":"C1","lines":[{"speaker":"Mme Morel","fr":"Bonjour. Je viens me plaindre du voisin du dessus. Il fait un tapage terrible !","en":"Hello. I've come to complain about the neighbor upstairs. He makes a terrible racket!","spans":[[62,68,"fr_tapage_noun"]]},{"speaker":"le gardien","fr":"Quel genre de bruit ?","en":"What kind of noise?","spans":[]},{"speaker":"Mme Morel","fr":"Des claquements de portes, des grincements de meubles à minuit...","en":"Doors banging, furniture creaking at midnight...","spans":[[4,15,"fr_claquement_noun"],[31,42,"fr_grincement_noun"]]},{"speaker":"le gardien","fr":"Je comprends. Je vais lui parler.","en":"I see. I'll talk to him.","spans":[]},{"speaker":"Mme Morel","fr":"Même ses chuchotements au téléphone traversent le plafond !","en":"Even his whispering on the phone comes through the ceiling!","spans":[[9,22,"fr_chuchotement_noun"]]},{"speaker":"le gardien","fr":"Les murs sont fins, ici. C'est une question de perception aussi.","en":"The walls are thin here. It's also a matter of perception.","spans":[]},{"speaker":"Mme Morel","fr":"Et hier, il jouait avec un pointeur laser, la lumière rouge entrait dans ma chambre !","en":"And yesterday he was playing with a laser pointer, the red light came into my bedroom!","spans":[]},{"speaker":"le gardien","fr":"D'accord, je lui parle aujourd'hui, avec subtilité.","en":"OK, I'll talk to him today, tactfully.","spans":[]},{"speaker":"Mme Morel","fr":"Merci. L'éloignement de la ville, c'était pour le calme !","en":"Thank you. I moved away from the city for the peace and quiet!","spans":[]},{"speaker":"le gardien","fr":"Je vous comprends, madame.","en":"I understand, madam.","spans":[]}]}],"musee/mysteres":[{"id":"C_R_adj_senses_07","title":"La soirée au musée","premise":"A couple visit a museum at night and look at a dramatic painting.","cefr":"C1","lines":[{"speaker":"Élise","fr":"Regarde ce tableau : la lune argentée au-dessus de la mer.","en":"Look at this painting: the silvery moon above the sea.","spans":[]},{"speaker":"Raphaël","fr":"Et ce personnage hautain, au premier plan. Il regarde tout le monde de haut !","en":"And that haughty figure in the foreground. He looks down on everyone!","spans":[]},{"speaker":"Élise","fr":"Il a un visage osseux, des jambes grêles... Il n'a pas l'air en forme !","en":"He's got a bony face, spindly legs... He doesn't look healthy!","spans":[]},{"speaker":"Raphaël","fr":"Ha ha ! Et derrière lui, une falaise vertigineuse.","en":"Ha ha! And behind him, a dizzying cliff.","spans":[[37,49,"fr_vertigineux_adj"]]},{"speaker":"Élise","fr":"Tu vois l'ombre furtive dans le coin ?","en":"Can you see the furtive shadow in the corner?","spans":[[16,23,"fr_furtif_adj"]]},{"speaker":"Raphaël","fr":"Un voleur, peut-être !","en":"A thief, maybe!","spans":[]},{"speaker":"Élise","fr":"Ce peintre a eu une triple vie : peintre, poète et marin.","en":"This painter had a triple life: painter, poet and sailor.","spans":[]},{"speaker":"Raphaël","fr":"Impressionnant. On va boire un verre ? J'ai les mains collantes après ce bonbon.","en":"Impressive. Should we go for a drink? My hands are sticky after that candy.","spans":[]},{"speaker":"Élise","fr":"D'accord, allons-y !","en":"OK, let's go!","spans":[]}]},{"id":"C_R_adj_senses_09","title":"La soirée film d'horreur","premise":"Two teenagers choose a movie to watch on a rainy evening.","cefr":"C1","lines":[{"speaker":"Nina","fr":"Il pleut, le ciel est morne... On regarde un film ?","en":"It's raining, the sky is gloomy... Should we watch a movie?","spans":[[22,27,"fr_morne_adj"]]},{"speaker":"Malik","fr":"Oui ! Un film d'horreur gothique, avec un château et des fantômes !","en":"Yes! A gothic horror movie, with a castle and ghosts!","spans":[[24,32,"fr_gothique_adj"]]},{"speaker":"Nina","fr":"Pas trop effrayant, hein. Je n'aime pas le surnaturel.","en":"Not too scary, OK? I don't like the supernatural.","spans":[[43,53,"fr_surnaturel_adj"]]},{"speaker":"Malik","fr":"Tu n'es pas très hardie !","en":"You're not very daring!","spans":[]},{"speaker":"Nina","fr":"Si ! Mais je préfère les films mélancoliques, avec de la belle musique.","en":"I am! But I prefer melancholy movies, with beautiful music.","spans":[[31,44,"fr_melancolique_adj"]]},{"speaker":"Malik","fr":"Alors celui-ci : l'image est un peu floue, c'est un vieux film.","en":"Then this one: the picture's a bit blurry, it's an old movie.","spans":[]},{"speaker":"Nina","fr":"Et l'affiche, avec ces couleurs criardes ?","en":"And the poster, with those garish colors?","spans":[]},{"speaker":"Malik","fr":"C'est un film des années soixante-dix !","en":"It's a seventies movie!","spans":[]},{"speaker":"Nina","fr":"Bon, d'accord. Avec du pop-corn !","en":"OK, fine. With popcorn!","spans":[]},{"speaker":"Malik","fr":"Je le prépare.","en":"I'll make it.","spans":[]}]}],"musee/labo":[{"id":"C_R_adj_senses_08","title":"La réunion du conseil","premise":"Two members of an advisory council discuss a new playground project.","cefr":"C1","lines":[{"speaker":"Mme Duval","fr":"Le conseil consultatif a voté pour le nouveau parc. C'était unanime !","en":"The advisory council voted for the new park. It was unanimous!","spans":[]},{"speaker":"M. Kone","fr":"Excellente nouvelle. Le sol sera en caoutchouc, pas glissant ?","en":"Excellent news. Will the ground be rubber, not slippery?","spans":[]},{"speaker":"Mme Duval","fr":"Oui, en matière synthétique, très fonctionnelle.","en":"Yes, synthetic material, very practical.","spans":[[16,27,"fr_synthetique_adj"],[34,47,"fr_fonctionnel_adj"]]},{"speaker":"M. Kone","fr":"Et les arbres ? Certains enfants sont allergiques au pollen.","en":"And the trees? Some children are allergic to pollen.","spans":[]},{"speaker":"Mme Duval","fr":"On a choisi des arbres sans pollen.","en":"We've chosen pollen-free trees.","spans":[]},{"speaker":"M. Kone","fr":"Parfait. Et l'éclairage le soir ?","en":"Perfect. And the lighting in the evening?","spans":[]},{"speaker":"Mme Duval","fr":"Une lumière diffuse, douce, pour ne pas gêner les voisins.","en":"Soft, diffuse lighting, so as not to disturb the neighbors.","spans":[[12,19,"fr_diffus_adj"]]},{"speaker":"M. Kone","fr":"Et l'aire de jeux est complémentaire de celle de l'école ?","en":"And is the playground complementary to the school's?","spans":[]},{"speaker":"Mme Duval","fr":"Exactement, pour les plus petits.","en":"Exactly, for the little ones.","spans":[]},{"speaker":"M. Kone","fr":"Bravo, c'est un beau projet.","en":"Well done, it's a lovely project.","spans":[]}]}],"musee/sens":[{"id":"C_R_abs_senses_01","title":"La maison de vacances","premise":"A family arrives at their vacation house and discovers it.","cefr":"A2","lines":[{"speaker":"Louise","fr":"Maman, quelle vue ! On voit la mer depuis ma chambre !","en":"Mom, what a view! You can see the sea from my room!","spans":[[14,17,"fr_vue_noun"]]},{"speaker":"Maman","fr":"Magnifique. Et il y a beaucoup de lumière dans le salon.","en":"Wonderful. And there's lots of light in the living room.","spans":[[34,41,"fr_lumiere_noun"]]},{"speaker":"Louise","fr":"Tu sens cette odeur ? C'est le jasmin dans le jardin.","en":"Can you smell that? It's the jasmine in the garden.","spans":[[14,19,"fr_odeur_noun"]]},{"speaker":"Maman","fr":"Oui. Et écoute ce silence ! Pas de bruit de voitures.","en":"Yes. And listen to that silence! No traffic noise.","spans":[[18,25,"fr_silence_noun"],[35,40,"fr_bruit_noun"]]},{"speaker":"Louise","fr":"On mange dehors, à l'ombre du grand arbre ?","en":"Should we eat outside, in the shade of the big tree?","spans":[[21,26,"fr_ombre_noun"]]},{"speaker":"Maman","fr":"Bonne idée. Regarde Papa, il fait un geste depuis la plage.","en":"Good idea. Look at Dad, he's waving from the beach.","spans":[[37,42,"fr_geste_noun"]]},{"speaker":"Louise","fr":"Il nous appelle ! On y va ?","en":"He's calling us! Should we go?","spans":[]},{"speaker":"Maman","fr":"D'accord. Mais d'abord, la crème solaire !","en":"OK. But suncream first!","spans":[]},{"speaker":"Louise","fr":"Maman, tu as un regard sévère, là !","en":"Mom, you've got a stern look on your face!","spans":[[16,22,"fr_regard_noun"]]},{"speaker":"Maman","fr":"Ha ha ! Parce que c'est important !","en":"Ha ha! Because it matters!","spans":[]}]}],"musee/lumieres":[{"id":"C_R_abs_senses_02","title":"La panne dans le grenier","premise":"Two siblings explore their grandparents' dark attic during a power cut.","cefr":"B1","lines":[{"speaker":"Lisa","fr":"Il fait noir ! Je ne vois rien dans cette obscurité.","en":"It's dark! I can't see anything in this darkness.","spans":[[42,51,"fr_obscurite_noun"]]},{"speaker":"Tom","fr":"Attends, j'allume la lampe de mon téléphone. Appuie sur la touche, là.","en":"Wait, I'll turn on my phone flashlight. Press that button there.","spans":[]},{"speaker":"Lisa","fr":"Voilà une petite lueur. Mais quel éclairage faible !","en":"There's a little glimmer. But what weak lighting!","spans":[[17,22,"fr_lueur_noun"],[34,43,"fr_eclairage_noun"]]},{"speaker":"Tom","fr":"Regarde, une silhouette au fond !","en":"Look, a figure at the back!","spans":[]},{"speaker":"Lisa","fr":"Ah ! Ah non, c'est un vieux manteau sur un cintre.","en":"Ah! Oh no, it's an old coat on a hanger.","spans":[]},{"speaker":"Tom","fr":"J'ai une drôle de sensation. Comme si quelqu'un nous regardait.","en":"I've got a funny feeling. As if someone was watching us.","spans":[]},{"speaker":"Lisa","fr":"Mon instinct me dit de redescendre !","en":"My instinct tells me to go back down!","spans":[]},{"speaker":"Tom","fr":"Beurk, une toile d'araignée sur ma main !","en":"Yuck, a cobweb on my hand!","spans":[]},{"speaker":"Lisa","fr":"Ha ha ! Ton visage plein de dégoût !","en":"Ha ha! The disgust on your face!","spans":[]},{"speaker":"Tom","fr":"Allez, on redescend.","en":"Come on, let's go down.","spans":[]}]}],"musee/trone":[{"id":"C_R_abs_power_01","title":"Le conseil municipal des jeunes","premise":"A mayor explains the new youth council to a teenager.","cefr":"A2","lines":[{"speaker":"le maire","fr":"Bienvenue au conseil municipal des jeunes, Zoé !","en":"Welcome to the youth council, Zoé!","spans":[]},{"speaker":"Zoé","fr":"Merci ! Mais quel est notre rôle, exactement ?","en":"Thank you! But what's our role, exactly?","spans":[[28,32,"fr_role_noun"]]},{"speaker":"le maire","fr":"Vous proposez des projets pour la ville. Un parc, une fête, un skatepark...","en":"You suggest projects for the town. A park, a festival, a skatepark...","spans":[]},{"speaker":"Zoé","fr":"Et nous avons le pouvoir de décider ?","en":"And do we have the power to decide?","spans":[[17,24,"fr_pouvoir_noun"]]},{"speaker":"le maire","fr":"Une partie. Le budget reste sous le contrôle de la mairie.","en":"Partly. The budget stays under the town hall's control.","spans":[[36,44,"fr_controle_noun"]]},{"speaker":"Zoé","fr":"Il y a des règles à respecter ?","en":"Are there rules to follow?","spans":[]},{"speaker":"le maire","fr":"Oui. Chaque projet passe par notre organisation : vote, budget, puis réalisation.","en":"Yes. Each project goes through our process: vote, budget, then completion.","spans":[[35,47,"fr_organisation_noun"]]},{"speaker":"Zoé","fr":"C'est une vraie institution !","en":"It's a real institution!","spans":[[16,27,"fr_institution_noun"]]},{"speaker":"le maire","fr":"Oui, et vous avez une certaine autorité. La puissance de la jeunesse !","en":"Yes, and you have some authority. The power of youth!","spans":[[31,39,"fr_autorite_noun"],[44,53,"fr_puissance_noun"]]},{"speaker":"Zoé","fr":"Super ! Ma première proposition : un skatepark !","en":"Great! My first proposal: a skatepark!","spans":[]}]}],"musee/assemblee":[{"id":"C_R_abs_power_02","title":"Le nouveau directeur","premise":"Two employees discuss their ambitious new manager.","cefr":"B2","lines":[{"speaker":"Sylvie","fr":"Tu as rencontré le nouveau directeur ?","en":"Have you met the new director?","spans":[]},{"speaker":"Karim","fr":"Oui. Il a beaucoup d'ambition. Il veut changer toute l'administration !","en":"Yes. He's very ambitious. He wants to change the whole management!","spans":[]},{"speaker":"Sylvie","fr":"Il a déjà pris l'initiative de supprimer les réunions du lundi.","en":"He's already taken the initiative of canceling the Monday meetings.","spans":[]},{"speaker":"Karim","fr":"Ça, c'est une bonne idée !","en":"Now that's a good idea!","spans":[]},{"speaker":"Sylvie","fr":"Mais il a une grande influence sur le patron. On va voir.","en":"But he's got a lot of influence over the boss. We'll see.","spans":[]},{"speaker":"Karim","fr":"Il a une vraie maîtrise des chiffres, en tout cas.","en":"He's really on top of the figures, anyway.","spans":[]},{"speaker":"Sylvie","fr":"Oui, mais il n'accepte pas bien la critique.","en":"Yes, but he doesn't take criticism well.","spans":[]},{"speaker":"Karim","fr":"Le règne de l'ancien directeur était plus calme.","en":"The old director's reign was calmer.","spans":[]},{"speaker":"Sylvie","fr":"J'ai hâte de voir les résultats.","en":"I'm keen to see the results.","spans":[]},{"speaker":"Karim","fr":"Moi aussi. Bon, on retourne travailler ?","en":"Me too. Right, should we get back to work?","spans":[]}]}],"musee/dirigeants":[{"id":"C_R_abs_power_03","title":"Le comité des fêtes","premise":"Members of a village festival committee prepare the summer fair.","cefr":"B1","lines":[{"speaker":"M. Lebrun","fr":"Bon, la réunion du comité des fêtes commence. Tout le monde est là ?","en":"Right, the festival committee meeting is starting. Is everyone here?","spans":[]},{"speaker":"Mme Carré","fr":"Oui. Vous avez l'autorisation de la mairie pour la fête du 14 Juillet ?","en":"Yes. Have you got permission from the town hall for the 14th of July party?","spans":[]},{"speaker":"M. Lebrun","fr":"Oui, mais il y a un nouveau règlement : pas de musique après une heure.","en":"Yes, but there's a new regulation: no music after one o'clock.","spans":[]},{"speaker":"Mme Carré","fr":"D'accord. Et les feux d'artifice ?","en":"OK. And the fireworks?","spans":[]},{"speaker":"M. Lebrun","fr":"Oups ! Un petit oubli : je n'ai pas demandé.","en":"Oops! A small oversight: I didn't ask.","spans":[]},{"speaker":"Mme Carré","fr":"Ce n'est pas grave, j'appelle demain. Vous m'avez donné un mandat pour la sécurité.","en":"Never mind, I'll call tomorrow. You gave me a mandate for safety.","spans":[]},{"speaker":"M. Lebrun","fr":"Merci. Il faut de la discipline avec les bénévoles, cette année.","en":"Thank you. We need discipline with the volunteers this year.","spans":[]},{"speaker":"Mme Carré","fr":"Et de la discrétion : la surprise du maire reste secrète !","en":"And discretion: the mayor's surprise stays secret!","spans":[]},{"speaker":"M. Lebrun","fr":"Bien sûr. Et le premier verre est offert aux anciens, c'est leur privilège.","en":"Of course. And the first drink is on the house for the elderly, it's their privilege.","spans":[]},{"speaker":"Mme Carré","fr":"Parfait. Réunion terminée !","en":"Perfect. Meeting over!","spans":[]}]}],"musee/chartes":[{"id":"C_R_abs_power_04","title":"L'adolescence","premise":"Two parents discuss how much freedom to give their teenage daughter.","cefr":"C1","lines":[{"speaker":"Christine","fr":"Emma veut aller au concert seule samedi. Elle veut plus d'autonomie.","en":"Emma wants to go to the concert on her own on Saturday. She wants more independence.","spans":[[58,67,"fr_autonomie_noun"]]},{"speaker":"Philippe","fr":"À quinze ans ? Je ne sais pas.","en":"At fifteen? I'm not sure.","spans":[]},{"speaker":"Christine","fr":"On ne peut pas la garder sous notre tutelle toute sa vie.","en":"We can't keep her under our wing all her life.","spans":[[36,43,"fr_tutelle_noun"]]},{"speaker":"Philippe","fr":"C'est vrai. Mais la semaine dernière, elle est rentrée à minuit. Il faut une sanction.","en":"That's true. But last week she got home at midnight. There has to be a punishment.","spans":[[77,85,"fr_sanction_noun"]]},{"speaker":"Christine","fr":"Pas de répression, Philippe. Il faut parler avec elle.","en":"No crackdowns, Philippe. We need to talk to her.","spans":[[7,17,"fr_repression_noun"]]},{"speaker":"Philippe","fr":"Elle fait de la manipulation : elle demande d'abord à toi, puis à moi !","en":"She plays us: she asks you first, then me!","spans":[[16,28,"fr_manipulation_noun"]]},{"speaker":"Christine","fr":"Ha ha ! C'est vrai. Elle est maligne.","en":"Ha ha! True. She's clever.","spans":[]},{"speaker":"Philippe","fr":"Et elle a l'hégémonie sur la télécommande de la télé !","en":"And she's got total control of the TV remote!","spans":[[12,21,"fr_hegemonie_noun"]]},{"speaker":"Christine","fr":"Bon, on dit oui pour le concert, mais avec un peu de retenue : retour à vingt-trois heures.","en":"OK, we say yes to the concert, but with a bit of restraint: home by eleven.","spans":[[53,60,"fr_retenue_noun"]]},{"speaker":"Philippe","fr":"D'accord.","en":"Agreed.","spans":[]}]}],"musee/guildes":[{"id":"C_R_abs_power_05","title":"Le festival du château","premise":"The organiser of a castle music festival talks to a local journalist.","cefr":"C1","lines":[{"speaker":"la journaliste","fr":"Merci de me recevoir. Vous êtes l'organisateur du festival depuis dix ans ?","en":"Thanks for seeing me. You've been organizing the festival for ten years?","spans":[[34,46,"fr_organisateur_noun"]]},{"speaker":"l'organisateur","fr":"Oui. Mon prédécesseur m'a passé le relais. J'espère trouver bientôt un successeur !","en":"Yes. My predecessor handed it over to me. I hope to find a successor soon!","spans":[[71,81,"fr_successeur_noun"]]},{"speaker":"la journaliste","fr":"Le château appartenait à l'aristocratie locale ?","en":"Did the castle belong to the local aristocracy?","spans":[[27,39,"fr_aristocratie_noun"]]},{"speaker":"l'organisateur","fr":"Oui, à une vieille famille de comtes. Aujourd'hui, c'est la commune qui le gère.","en":"Yes, to an old family of counts. Today the town runs it.","spans":[]},{"speaker":"la journaliste","fr":"Le festival est soutenu par qui ?","en":"Who supports the festival?","spans":[]},{"speaker":"l'organisateur","fr":"Par un groupement d'associations locales. Leur contribution est essentielle.","en":"A group of local associations. Their contribution is essential.","spans":[[7,17,"fr_groupement_noun"],[47,59,"fr_contribution_noun"]]},{"speaker":"la journaliste","fr":"Et les bénévoles ?","en":"And the volunteers?","spans":[]},{"speaker":"l'organisateur","fr":"Leur implication est incroyable. Deux cents personnes !","en":"Their involvement is incredible. Two hundred people!","spans":[[5,16,"fr_implication_noun"]]},{"speaker":"la journaliste","fr":"Il y a des artistes suisses cette année ?","en":"Are there Swiss artists this year?","spans":[]},{"speaker":"l'organisateur","fr":"Oui, la Confédération helvétique est notre invitée d'honneur.","en":"Yes, Switzerland is our guest of honor.","spans":[[8,21,"fr_confederation_noun"]]},{"speaker":"la journaliste","fr":"Et la concurrence des grands festivals ?","en":"And the competition from the big festivals?","spans":[]},{"speaker":"l'organisateur","fr":"Pas de domination ici. On reste petits, mais sympas !","en":"No one dominates here. We stay small, but friendly!","spans":[[7,17,"fr_domination_noun"]]}]}]};
